arguments.query:
PREFIX cto: <https://nfdi4culture.de/ontology/>
PREFIX nfdicore: <https://nfdi.fiz-karlsruhe.de/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>

SELECT DISTINCT ?item ?itemLabel ?person ?personLabel ?description
WHERE {
  {
    SELECT DISTINCT ?person
    WHERE {
      ?person a nfdicore:NFDI_0000004 .
      OPTIONAL { ?person rdfs:label ?personRdfsLabel }
      OPTIONAL { ?person schema:name ?personName }
      BIND(COALESCE(?personRdfsLabel, ?personName, STR(?person)) AS ?personLabel)
      FILTER(CONTAINS(LCASE(STR(?personLabel)), LCASE("Beethoven")))
    }
    LIMIT 10
  }
  ?item cto:CTO_0001009 ?person .
  OPTIONAL { ?person rdfs:label ?personRdfsLabel }
  OPTIONAL { ?person schema:name ?personName }
  OPTIONAL { ?item rdfs:label ?itemRdfsLabel }
  OPTIONAL { ?item schema:name ?itemName }
  OPTIONAL { ?item schema:description ?description }
  BIND(COALESCE(?personRdfsLabel, ?personName, STR(?person)) AS ?personLabel)
  BIND(COALESCE(?itemRdfsLabel, ?itemName, STR(?item)) AS ?itemLabel)
}
ORDER BY LCASE(STR(?itemLabel))
LIMIT 50

