arguments.query:
PREFIX nfdicore: <https://nfdi.fiz-karlsruhe.de/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>

SELECT ?subjectArea ?subjectAreaLabel (COUNT(DISTINCT ?portal) AS ?portalCount)
WHERE {
  ?portal a nfdicore:NFDI_0000123 ;
    nfdicore:NFDI_0000211 ?subjectArea .
  OPTIONAL { ?subjectArea rdfs:label ?subjectAreaRdfsLabel }
  OPTIONAL { ?subjectArea schema:name ?subjectAreaName }
  BIND(COALESCE(?subjectAreaRdfsLabel, ?subjectAreaName, STR(?subjectArea)) AS ?subjectAreaLabel)
}
GROUP BY ?subjectArea ?subjectAreaLabel
ORDER BY DESC(?portalCount) LCASE(STR(?subjectAreaLabel))

